import{_ as n,C as o,o as t,c as r,a2 as s,b as l,w as a,a as d,E as h,a3 as c}from"./chunks/framework.CZqXuAiL.js";const v=JSON.parse(`{"title":"Antivirus Layer (Protection Plus)","description":"Protection's on-access antivirus — threat-intel updates, the shipped YARA rule bundle, the MalwareBazaar SHA-256 blocklist, and the fsnotify scan pipeline that quarantines malicious uploads.","frontmatter":{"title":"Antivirus Layer (Protection Plus)","description":"Protection's on-access antivirus — threat-intel updates, the shipped YARA rule bundle, the MalwareBazaar SHA-256 blocklist, and the fsnotify scan pipeline that quarantines malicious uploads."},"headers":[],"relativePath":"protection/user-guide/antivirus.md","filePath":"protection/user-guide/antivirus.md","lastUpdated":null}`),p={name:"protection/user-guide/antivirus.md"};function u(g,e,k,m,y,b){const i=o("Mermaid");return t(),r("div",null,[e[1]||(e[1]=s(`<h1 id="antivirus-layer-protection-plus" tabindex="-1">Antivirus Layer (Protection Plus) <a class="header-anchor" href="#antivirus-layer-protection-plus" aria-label="Permalink to &quot;Antivirus Layer (Protection Plus)&quot;">​</a></h1><p>The antivirus layer is Protection&#39;s fast path against malicious <strong>files</strong>: the moment a file lands in a watched upload directory, it is hashed and pattern-scanned, and matches hit the default <code>malware</code> rule — <strong>quarantine + alert</strong>.</p><p>It has three parts working together:</p><ul><li><strong>Threat intel</strong> — downloads and refreshes the YARA rule bundle and the SHA-256 hash blocklist (<code>protection rules update</code>, plus automatic daily refresh).</li><li><strong>On-access scanning</strong> — an fsnotify watcher that scans every file as it is created or modified.</li><li><strong>Optional CLI scanners</strong> — periodic full-tree sweeps via the <code>yara</code> and <code>trivy</code> binaries, when installed.</li></ul><div class="warning custom-block"><p class="custom-block-title">DRY RUN FIRST</p><p>As with everything in Protection, the global <code>general.dry_run: true</code> safety switch applies: matches are detected and alerted, but no file is quarantined until you arm the daemon. See <a href="./actions-rules">Actions &amp; Rules</a>.</p></div><hr><h2 id="setup-in-3-steps" tabindex="-1">Setup in 3 steps <a class="header-anchor" href="#setup-in-3-steps" aria-label="Permalink to &quot;Setup in 3 steps&quot;">​</a></h2><ol><li><p><strong>Fetch the threat intel:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rules</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>This downloads the YARA rule bundle to <code>intel.rules_dir</code> (<code>/etc/protection/yara/protection.yar</code>) and the MalwareBazaar SHA-256 blocklist to <code>intel.hashlist_file</code> (<code>/var/lib/protection/blocklist.sha256</code>). The daemon then refreshes both automatically every <code>intel.update_interval</code> (default <code>24h</code>).</p></li><li><p><strong>(Optional) install the yara CLI</strong> for pattern scanning beyond hash matching:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yara</span></span></code></pre></div><p>Without it, hash-blocklist scanning still works; YARA checks simply no-op (see <a href="#optional-clis-yara-and-trivy">Optional CLIs</a>).</p></li><li><p><strong>Watch it work.</strong> Drop a test file and add its hash to your custom blocklist — the EICAR-style way to prove the pipeline end to end without real malware:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;protection antivirus test payload&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/pterodactyl/volumes/test.bin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/pterodactyl/volumes/test.bin</span></span></code></pre></div><p>Put the resulting 64-char hash (one per line) into a file, point <code>intel.custom_hashlist</code> at it, and restart:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">intel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  custom_hashlist</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/etc/protection/custom-blocklist.sha256</span></span></code></pre></div><p>Within ~500 ms of writing the file you should see a <strong>critical</strong> &quot;Known malware (hash blocklist)&quot; event in the log — and, if <code>dry_run</code> is off, the file moved to <code>actions.file.quarantine_dir</code> with mode <code>000</code>.</p></li></ol><hr><h2 id="threat-intel-system" tabindex="-1">Threat-intel system <a class="header-anchor" href="#threat-intel-system" aria-label="Permalink to &quot;Threat-intel system&quot;">​</a></h2><p>The intel manager owns both downloaded assets — the YARA rules and the hash blocklist.</p><ul><li><strong>Manual refresh:</strong> <code>protection rules update</code> runs one update pass immediately.</li><li><strong>Automatic refresh:</strong> with <code>intel.enabled: true</code>, the daemon re-runs the same pass every <code>intel.update_interval</code> (default <code>24h</code> — a daily refresh).</li><li><strong>Atomic writes:</strong> every download lands in a temp file in the destination directory and is <code>rename(2)</code>d into place, so readers never see a partial file. Temp files live next to the destination deliberately: the rename must stay on one filesystem, and systemd sandboxes can make <code>/tmp</code> read-only for the service.</li><li><strong>Identified downloads:</strong> all requests carry a real <code>User-Agent</code> — <code>protection/&lt;version&gt; +https://github.com/AnAverageBeing/protection</code> — so upstream services (abuse.ch etc.) can identify the client.</li><li><strong>Fault-tolerant:</strong> the rules and the hashlist are fetched <strong>independently</strong>. If one source fails, the other still updates; the command reports a <em>partial</em> update instead of failing wholesale, and the daemon logs a warning and keeps the previous copy.</li></ul><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">intel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  rules_dir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/etc/protection/yara</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  rules_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://raw.githubusercontent.com/AnAverageBeing/protection/main/rules/protection.yar&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  hashlist_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://bazaar.abuse.ch/export/txt/sha256/recent/&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  hashlist_file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/var/lib/protection/blocklist.sha256</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  custom_hashlist</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  update_interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">24h</span></span></code></pre></div><hr><h2 id="yara-rule-bundle" tabindex="-1">YARA rule bundle <a class="header-anchor" href="#yara-rule-bundle" aria-label="Permalink to &quot;YARA rule bundle&quot;">​</a></h2><p>The shipped <code>protection.yar</code> is a curated set of <strong>9 rules</strong> aimed at Linux hosting-abuse threats seen on shared/VPS/game nodes:</p><table tabindex="0"><thead><tr><th>Rule</th><th>Detects</th><th>Severity</th></tr></thead><tbody><tr><td><code>Webshell_Generic_EvalBase64</code></td><td>Generic PHP webshells: <code>eval(gzinflate/str_rot13/base64_decode(...))</code>, and <code>system</code>/<code>shell_exec</code>/<code>passthru</code>/<code>popen</code>/<code>proc_open</code>/<code>assert</code> fed from <code>$_GET</code>/<code>$_POST</code>/<code>$_REQUEST</code>/<code>$_COOKIE</code></td><td>high</td></tr><tr><td><code>Webshell_Known_Families</code></td><td>Known webshell families: c99, r57, WSO (&quot;Web Shell by oRb&quot;), b374k, FilesMan, pwnshell, minishell</td><td>high</td></tr><tr><td><code>Miner_Generic</code></td><td>Cryptocurrency miners: <code>stratum+tcp/ssl://</code> pool URLs, RandomX, cryptonight, xmrig and its config markers</td><td>high</td></tr><tr><td><code>Tor_Relay_Binary</code></td><td>Tor daemon binary markers — catches a <strong>renamed</strong> <code>tor</code> binary (needs 2 of 5 embedded strings)</td><td>high</td></tr><tr><td><code>Mirai_Variant</code></td><td>Mirai-family botnet markers (watchdog abuse, <code>TSource Engine Query</code>, JS-challenge bypass paths, …)</td><td>critical</td></tr><tr><td><code>IRC_Bot</code></td><td>IRC bot / eggdrop-style command patterns (<code>PRIVMSG #</code>, <code>JOIN #</code>, <code>!ddos</code>, <code>!scan</code>; needs 3 of 5)</td><td>medium</td></tr><tr><td><code>Linux_Backdoor_Generic</code></td><td>Reverse-shell one-liners in scripts: <code>/dev/tcp/</code>, <code>nc -e /bin</code>, <code>ncat -e /bin</code>, <code>socat exec:</code>, <code>bash -i &gt;&amp;</code></td><td>high</td></tr><tr><td><code>Linux_Privesc_Exploit</code></td><td>Known privesc exploit markers: DirtyPipe (CVE-2022-0847), DirtyCow (CVE-2016-5195), PwnKit (CVE-2021-4034)</td><td>high</td></tr><tr><td><code>Crypto_Stealer_Script</code></td><td>Clipboard/crypto stealer scripts: a BTC-address shape paired with <code>xclip</code>/<code>wl-paste</code>/<code>replace_clipboard</code></td><td>medium</td></tr></tbody></table><h3 id="customising-the-rules" tabindex="-1">Customising the rules <a class="header-anchor" href="#customising-the-rules" aria-label="Permalink to &quot;Customising the rules&quot;">​</a></h3><ul><li><strong>Self-host the bundle:</strong> point <code>intel.rules_url</code> at your own URL (an internal mirror, a pinned commit, your own fork) and <code>protection rules update</code> will pull from there instead.</li><li><strong>Add your own rules:</strong> drop extra <code>.yar</code> files into <code>intel.rules_dir</code>. The on-access scanner prefers the single compiled bundle <code>protection.yar</code> when it exists, and otherwise scans the whole rules directory recursively; the periodic <code>yara</code> sweep always scans the directory recursively, so extra files are picked up there regardless.</li><li>Note: <code>rules update</code> overwrites <code>protection.yar</code> itself — keep local additions in <strong>separate files</strong>, not edits to the bundle.</li></ul><hr><h2 id="sha-256-hash-blocklist" tabindex="-1">SHA-256 hash blocklist <a class="header-anchor" href="#sha-256-hash-blocklist" aria-label="Permalink to &quot;SHA-256 hash blocklist&quot;">​</a></h2><p>The blocklist is an in-memory set of known-bad SHA-256 hashes, looked up before any YARA work happens — exact, zero-false-positive matching for known malware.</p><ul><li><p><strong>Source:</strong> MalwareBazaar exports. The parser accepts the export <strong>raw or zipped</strong> (it sniffs the <code>PK\\x03\\x04</code> zip magic and transparently streams out the first file), lowercases and validates every line, and skips comments and junk.</p></li><li><p><strong>Recent vs full:</strong> the default URL is the <code>recent</code> export (last ~48 h — small and fast). For complete coverage, opt in to the full export:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">intel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  hashlist_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://bazaar.abuse.ch/export/txt/sha256/full/&quot;</span></span></code></pre></div><p>Trade-off: the full export is <strong>~1.1M hashes</strong>, and every hash lives in the daemon&#39;s in-memory set — expect a few hundred MB of extra RAM.</p></li><li><p><strong>Your own hashes:</strong> <code>intel.custom_hashlist</code> points at a second file (one SHA-256 per line, <code>#</code> comments allowed). It is <strong>merged</strong> into the set at load time and never overwritten by updates — ideal for internal IOCs and test hashes.</p></li><li><p><strong>Streaming parse:</strong> the download goes straight to a temp file on disk and is parsed line-by-line; even the multi-hundred-MB full export never sits in memory at once. This is what lets the daemon ingest the full list while staying under its systemd memory cap (256 MB <code>MemoryMax</code> in the packaged unit) during the update itself — the steady-state RAM cost is only the resulting hash set.</p></li></ul><hr><h2 id="on-access-scanning-pipeline" tabindex="-1">On-access scanning pipeline <a class="header-anchor" href="#on-access-scanning-pipeline" aria-label="Permalink to &quot;On-access scanning pipeline&quot;">​</a></h2><p>The <code>onaccess</code> detector is the hot path. Enabled by default, it watches <code>detectors.onaccess.watch_paths</code> (your panel volumes / upload dirs) and scans files the moment they are written.</p>`,26)),(t(),l(c,null,{default:a(()=>[h(i,{id:"mermaid-286",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5Bfsnotify%20create%2Fwrite%20event%3Cbr%2F%3Erecursive%20watch%20on%20watch_paths%5D%20--%3E%20B%7BSettle%20debounce%3Cbr%2F%3Equiet%20for%20settle_ms%3F%7D%0A%20%20%20%20B%20--%20still%20being%20written%20--%3E%20B%0A%20%20%20%20B%20--%20settled%20--%3E%20C%7BWhitelisted%20path%3F%7D%0A%20%20%20%20C%20--%20yes%20--%3E%20Z%5Bskip%5D%0A%20%20%20%20C%20--%20no%20--%3E%20D%5BSHA-256%20lookup%3Cbr%2F%3Evs%20hash%20blocklist%5D%0A%20%20%20%20D%20--%20match%2C%20%E2%89%A4512%20MiB%20--%3E%20E%5BCritical%20malware%20event%5D%0A%20%20%20%20D%20--%20no%20match%20--%3E%20F%5BYARA%20scan%3Cbr%2F%3Eprotection.yar%20or%20-r%20rules_dir%5D%0A%20%20%20%20F%20--%20rule%20match%2C%20%E2%89%A464%20MiB%20--%3E%20G%5BHigh%20malware%20event%5D%0A%20%20%20%20F%20--%20no%20match%20--%3E%20Z%0A%20%20%20%20E%20--%3E%20H%5Bmalware%20rule%3A%3Cbr%2F%3Equarantine_file%20%2B%20alert%5D%0A%20%20%20%20G%20--%3E%20H%0A%20%20%20%20H%20--%3E%20I%5BFile%20moved%20to%20quarantine_dir%2C%3Cbr%2F%3Echmod%20000%20%2B%20Discord%2Femail%2Fwebhook%20alert%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s('<p>How it works, in order:</p><ol><li><strong>Recursive fsnotify watch.</strong> Every directory under each watch path gets an inotify watch; newly created directories (including moved-in trees) are added on the fly, so files inside them never go unseen.</li><li><strong>Settle debounce.</strong> Editors and downloaders write in bursts; scanning a half-written file wastes I/O and can misfire. A path is only scanned once it has been quiet for <code>settle_ms</code> (default 500 ms).</li><li><strong>SHA-256 lookup.</strong> The file is hashed and checked against the blocklist (files over 512 MiB are skipped — hashing them on every write costs more than the lookup is worth). A hit is a <strong>critical</strong> &quot;Known malware (hash blocklist)&quot; event with the hash as evidence.</li><li><strong>YARA scan.</strong> Otherwise (and additionally) the file is scanned with the yara CLI against <code>protection.yar</code> — falling back to a recursive scan of the whole <code>rules_dir</code> when the bundle file is absent. Files over 64 MiB are skipped; a single scan is capped at 30 s so a pathological file can&#39;t stall the workers. A match is a <strong>high</strong> &quot;Malware detected by YARA rule&quot; event with the rule name as evidence.</li><li><strong>Enforcement.</strong> Both event kinds have category <code>malware</code>, so they hit the default <code>malware</code> rule (<code>min_severity: high</code>, actions <code>quarantine_file, alert</code>): the file is moved to the quarantine dir and chmodded <code>000</code> (evidence preserved), and an alert goes out. With <code>dry_run: true</code>, only the alert fires.</li></ol><p>Scanning runs in a bounded worker pool (2 concurrent scans) decoupled from the engine&#39;s scan tick, with a 1000-event queue that drops the oldest entries (with a warning) if a write storm ever fills it. Watcher errors are tolerated — the periodic sweeps are the backstop.</p><div class="tip custom-block"><p class="custom-block-title">WHITELIST</p><p>Paths under <code>whitelist.paths</code> are never scanned, even if they sit inside a watch path — use it for trusted build output or anything Protection must never touch.</p></div><hr><h2 id="optional-clis-yara-and-trivy" tabindex="-1">Optional CLIs: yara and trivy <a class="header-anchor" href="#optional-clis-yara-and-trivy" aria-label="Permalink to &quot;Optional CLIs: yara and trivy&quot;">​</a></h2><p>Protection shells out to external scanners instead of linking their libraries (this keeps the daemon a CGO-free static binary), and both are <strong>strictly optional</strong>:</p><ul><li><strong><code>yara</code></strong> — used by both the on-access pipeline and the periodic <code>detectors.yara</code> full-tree sweep (<code>interval</code>, default 10 min, over <code>scan_paths</code>). If the binary is not in <code>PATH</code>, the periodic detector reports itself unavailable and never scans, and on-access YARA checks silently disable themselves — hash matching is unaffected.</li><li><strong><code>trivy</code></strong> — <code>detectors.trivy</code> scans container images for vulnerabilities (one alert-only event per image with HIGH/CRITICAL counts, gated by <code>min_severity</code>). Same model: a missing binary means a permanent no-op, not an error.</li></ul><p>Nothing in Protection fails to start or spams logs because these binaries are absent; install them when you want the extra coverage.</p><hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><strong><a href="./actions-rules">Actions &amp; Rules →</a></strong> — what <code>quarantine_file</code> does and how to change the <code>malware</code> rule.</li><li><strong><a href="./detection">Detection Engines →</a></strong> — where on-access fits among the other detectors.</li><li><strong><a href="./cli">CLI Reference →</a></strong> — <code>protection rules update</code> and friends.</li></ul>',12))])}const w=n(p,[["render",u]]);export{v as __pageData,w as default};
